head.script:
scwin.onpageload = function() {
	var data1 = [];
	var data2 = [];
	for (var i = 0; i < 40; i++) {
		data1.push("R_" + (i + 1));
		data1.push(i + "");
		data2.push(i + "");
		data2.push(i + "");
	}
	dataList1.setData(data1);
	dataList2.setData(data2);
	dataList3.setData(data2);
	dataMap2.set("key1", "5");
	dataMap2.set("key2", "10");
	dataMap2.set("key3", "6");
};

scwin.checkVal1 = function() {
	const checkVal1 = (document.getElementById('selectbox1_label') || document.getElementById('mf_selectbox1_label')).innerText == 6;
	const checkVal2 = (document.getElementById('wframe1_selectbox1_label') || document.getElementById('mf_wframe1_selectbox1_label')).innerText == 6;
	const checkVal3 = (document.getElementById('wframe1_wframe1_selectbox1_label') || document.getElementById('mf_wframe1_wframe1_selectbox1_label')).innerText == 6;
	return checkVal1 && checkVal2 && checkVal3;
};
scwin.checkVal2 = function() {
	return (document.getElementById('selectbox1_itemTable_main') || document.getElementById('mf_selectbox1_itemTable_main')).querySelectorAll('tr').length > 2;
};
scwin.checkVal3 = function() {
	return (document.getElementById('wframe1_selectbox1_itemTable_main') || document.getElementById('mf_wframe1_selectbox1_itemTable_main')).querySelectorAll('tr').length == 2;
};
scwin.checkVal4 = function() {
	return (document.getElementById('wframe1_wframe1_selectbox1_itemTable_main') || document.getElementById('mf_wframe1_wframe1_selectbox1_itemTable_main')).querySelectorAll('tr').length == 2;
};
scwin.checkVal5 = function() {
	return (document.getElementById('wframe1_wframe1_selectbox1_itemTable_main') || document.getElementById('mf_wframe1_wframe1_selectbox1_itemTable_main')).querySelectorAll('tr').length > 2;
};
